/* Lawn: a pane shrinks into the parked tray. The base state is the final frame; the animation runs from the start. */
.lawn-park{transform-box:view-box;transform-origin:144px 34px;transform:translate(-8px,110px) scale(.8,.186)}
.play .lawn-park{animation:lawn-park .9s cubic-bezier(.5,0,.2,1) .5s backwards}
.play .lawn-parked{animation:lawn-fadein .3s ease-out 1.2s backwards}
@keyframes lawn-park{from{transform:none}}
@keyframes lawn-fadein{from{opacity:0}}
